<?php

namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

class PublicSparePartsRequestPresentation
{
    public function handle(Request $request, Closure $next): Response
    {
        $response = $next($request);
        if (! method_exists($response, 'getContent') || ! method_exists($response, 'setContent')) return $response;

        $html = (string) $response->getContent();
        if ($html === '' || ! str_contains($html, '</body>')) return $response;

        $assetLookup = route('public.asset.lookup');
        $partsLookup = route('public.spare-parts.lookup');
        $today = now()->toDateString();
        $time = now()->addHour()->format('H:i');

        $injection = <<<HTML
