-shadow:0 0 0 2px rgba(223,11,39,.05)}.sp-search{display:grid;grid-template-columns:1fr auto;gap:8px}.sp-search button,.sp-btn{border:0;border-radius:9px;background:#071f4d;color:#fff;padding:0 18px;min-height:48px;font:inherit;font-size:10px;font-weight:900;cursor:pointer}.sp-result{display:none;margin-top:10px;padding:12px;border:1px solid #bfe6d4;border-radius:10px;background:#f1fbf6;font-size:9.5px;line-height:1.8}.sp-result.show{display:block}.sp-parts{margin-top:10px;border:1px solid #e1e8f0;border-radius:10px;overflow:hidden}.sp-part{display:grid;grid-template-columns:minmax(170px,1.6fr) 120px 110px 95px;gap:8px;align-items:center;padding:10px 12px;border-bottom:1px solid #edf1f5;font-size:9px}.sp-part:last-child{border:0}.sp-part strong{display:block;color:#071f4d;font-size:10px}.sp-part small{color:#7b8798}.sp-status{display:inline-flex;justify-content:center;padding:5px 7px;border-radius:999px;font-weight:900}.sp-status.ok{background:#e6f7ef;color:#168457}.sp-status.low{background:#fff4d9;color:#9a6800}.sp-status.no{background:#ffe9ec;color:#c2263d}.sp-part button{border:0;border-radius:7px;background:#0d3970;color:#fff;padding:8px;font:inherit;font-size:8.5px;font-weight:900;cursor:pointer}.sp-manual{margin-top:12px;padding-top:12px;border-top:1px dashed #d8e1eb}.sp-note{padding:10px 12px;border-radius:9px;background:#eef5ff;color:#31547f;font-size:9px;line-height:1.7}.sp-selected{padding:10px 12px;border-radius:9px;background:#f1fbf6;border:1px solid #ccebdc;color:#176a49;font-size:9.5px;font-weight:800}.sp-hidden{display:none!important}@media(max-width:900px){.spare-wrap{grid-template-columns:1fr}.spare-side{position:static;order:-1}.sp-grid.three{grid-template-columns:1fr 1fr}.sp-part{grid-template-columns:1fr 90px}.sp-part>*:nth-child(2),.sp-part>*:nth-child(3){display:none}}@media(max-width:600px){.sp-grid,.sp-grid.three,.sp-choice{grid-template-columns:1fr}.sp-full{grid-column:auto}.sp-card{padding:14px}.spare-mode .submit{min-width:0;width:100%}}
