<div id="spUnregisteredAsset" class="sp-manual sp-hidden"><div class="sp-grid three"><label class="sp-label">\${ar?'نوع المعدة':'Equipment Type'}<input id="spAssetType" placeholder="Generator / HVAC"></label><label class="sp-label">\${ar?'الشركة المصنعة':'Manufacturer'}<input id="spBrand" placeholder="Cummins"></label><label class="sp-label">\${ar?'الموديل':'Model'}<input id="spModel"></label><label class="sp-label">\${ar?'الرقم التسلسلي':'Serial Number'}<input id="spSerial"></label></div></div>
