<div class="sp-card"><div class="sp-title"><span class="num">2</span><span>\${ar?'تفاصيل قطع الغيار المطلوبة':'Required Spare Parts'}</span></div><p class="sp-sub">\${ar?'ابحث في مستودع UNIFCO أو اختر قطعة مرتبطة بالأصل. حالة المخزون المعروضة لا تقوم بحجز الكمية حتى اعتماد الطلب.':'Search UNIFCO inventory. Stock is not reserved until approval.'}</p><div class="sp-search"><input id="spPartSearch" placeholder="\${ar?'رقم القطعة أو اسمها':'Part number or name'}"><button type="button" id="spPartLookup">\${ar?'بحث في المستودع':'Search Inventory'}</button></div><div id="spParts" class="sp-parts"><div class="sp-note">\${ar?'ابدأ البحث لعرض القطع وحالة التوفر.':'Search to show parts and availability.'}</div></div><div class="sp-manual"><div class="sp-choice"><label><input id="spDontKnow" type="checkbox"><span>\${ar?'لا أعرف رقم القطعة — ساعدني في تحديدها':'I do not know the part'}</span></label><label><input id="spManualPart" type="checkbox"><span>\${ar?'إدخال قطعة يدويًا':'Enter part manually'}</span></label></div><div id="spManualFields" class="sp-grid three" style="margin-top:10px"><label class="sp-label">\${ar?'اسم القطعة':'Part Name'}<input id="spPartName"></label><label class="sp-label">\${ar?'رقم القطعة':'Part Number'}<input id="spPartNo"></label><label class="sp-label">\${ar?'رقم OEM':'OEM Number'}<input id="spOem"></label><label class="sp-label">\${ar?'الكمية':'Quantity'}<input id="spQty" type="number" min="1" value="1"></label></div><div id="spSelectedPart" class="sp-selected" style="margin-top:10px">\${ar?'لم يتم اختيار قطعة بعد.':'No part selected yet.'}</div></div></div>
<div class="sp-card"><div class="sp-title"><span class="num">3</span><span>\${ar?'تفاصيل الطلب':'Request Details'}</span></div><div class="sp-grid three"><label class="sp-label">\${ar?'نوع الطلب':'Request Type'}<select id="spRequestType"><option value="quotation">\${ar?'عرض سعر قطع غيار':'Spare Parts Quotation'}</option><option value="parts_installation">\${ar?'قطع غيار + تركيب':'Parts + Installation'}</option><option value="inspection">\${ar?'زيارة فني لتحديد القطعة':'Technical Inspection'}</option></select></label><label class="sp-label">\${ar?'الأولوية':'Priority'}<select id="spPriority"><option value="NORMAL">\${ar?'عادي':'Normal'}</option><option value="PRIORITY">\${ar?'مهم':'Priority'}</option><option value="URGENT">\${ar?'عاجل':'Urgent'}</option></select></label><label class="sp-label">\${ar?'المنطقة':'Region'}<select id="spArea"><option value="Riyadh">\${ar?'الرياض':'Riyadh'}</option><option value="Makkah">\${ar?'مكة المكرمة':'Makkah'}</option><option value="Eastern Province">\${ar?'المنطقة الشرقية':'Eastern Province'}</option><option value="Madinah">\${ar?'المدينة المنورة':'Madinah'}</option><option value="Other">\${ar?'أخرى':'Other'}</option></select></label><label class="sp-label">\${ar?'المدينة':'City'}<input id="spCity" required></label><label class="sp-label">\${ar?'التاريخ المطلوب':'Requested Date'}<input id="spDate" type="date" min="{$today}" value="{$today}" required></label><label class="sp-label">\${ar?'الوقت المفضل':'Preferred Time'}<input id="spTime" type="time" value="{$time}" required></label><label class="sp-label sp-full">\${ar?'ملاحظات إضافية':'Additional Notes'}<textarea id="spNotes" placeholder="\${ar?'اكتب أي تفاصيل تساعد الفريق في تحديد القطعة أو التجهيز للتركيب...':'Add any details that help identify or prepare the part...'}"></textarea></label></div></div>
<div class="sp-card"><div class="sp-title"><span class="num">4</span><span>\${ar?'المرفقات والمساعدة':'Attachments & Help'}</span></div><p class="sp-sub">\${ar?'يمكنك إرفاق صورة القطعة أو لوحة بيانات الأصل أو تقارير سابقة.':'Attach part photos, asset nameplate or reports.'}</p><div class="sp-grid three"><label class="sp-label upload">\${ar?'صور القطعة / الأصل':'Part / Asset Photos'}<input type="file" id="spPhotos" name="equipment_photos[]" multiple accept="image/jpeg,image/png,image/webp"></label><label class="sp-label upload">\${ar?'صور لوحة البيانات / المشكلة':'Nameplate / Problem Photos'}<input type="file" id="spProblemPhotos" name="problem_photos[]" multiple accept="image/jpeg,image/png,image/webp"></label><label class="sp-label upload">\${ar?'مستندات أو تقارير':'Documents / Reports'}<input type="file" id="spReports" name="previous_reports[]" multiple accept=".pdf,.xlsx,.xls,.doc,.docx,.jpg,.jpeg,.png"></label></div></div>
</div><aside class="spare-side"><h3>\${ar?'ملخص الطلب':'Request Summary'}</h3><div class="sp-note">\${ar?'سيتم إنشاء رقم التذكرة تلقائيًا فور الإرسال وفق نفس آلية التذاكر المعتمدة في المنصة.':'A ticket number will be issued automatically on submission.'}</div><div class="summary-row"><span>\${ar?'نوع الخدمة':'Service'}</span><b>\${ar?'قطع غيار':'Spare Parts'}</b></div><div class="summary-row"><span>\${ar?'العميل':'Customer'}</span><b id="sumCustomer">—</b></div><div class="summary-row"><span>\${ar?'الأصل':'Asset'}</span><b id="sumAsset">—</b></div><div class="summary-row"><span>\${ar?'القطعة':'Part'}</span><b id="sumPart">—</b></div><div class="summary-row"><span>\${ar?'المخزون':'Inventory'}</span><b id="sumStock">\${ar?'بانتظار الاختيار':'Pending'}</b></div></aside></div>`;
const submitbar=form.querySelector('.submitbar');form.insertBefore(panel,submitbar);
const genericUploads=form.querySelectorAll('#requestForm>.section:nth-of-type(4) input[type=file]');genericUploads.forEach(x=>x.disabled=true);
let selectedAsset=null,selectedPart=null,selectedAvailability='';
const setVal=(n,v)=>{const e=generic(n);if(e)e.value=v??''};
