const isSpare=()=>document.querySelector('input[name=request_subtype]:checked')?.value==='SPARE_PARTS_QUOTE';
function syncMode(){document.body.classList.toggle('spare-mode',isSpare());if(isSpare()){const btn=form.querySelector('.submit');if(btn)btn.textContent=ar?'إرسال الطلب وإنشاء تذكرة':'Submit & Create Ticket';setVal('service_category','Spare Parts');setVal('request_intent','QUOTATION')}else{const btn=form.querySelector('.submit');if(btn)btn.textContent=ar?'إرسال الطلب':'Submit Request'}}
document.querySelectorAll('input[name=request_subtype],input[name=request_intent]').forEach(x=>x.addEventListener('change',()=>setTimeout(syncMode,0)));syncMode();
document.querySelectorAll('input[name=sp_asset_mode]').forEach(x=>x.addEventListener('change',()=>{const reg=document.querySelector('input[name=sp_asset_mode]:checked').value==='registered';document.getElementById('spRegisteredAsset').classList.toggle('sp-hidden',!reg);document.getElementById('spUnregisteredAsset').classList.toggle('sp-hidden',reg);if(!reg){selectedAsset=null;setVal('asset_id','')}}));
document.getElementById('spAssetLookup').addEventListener('click',async()=>{const key=document.getElementById('spAssetKey').value.trim(),box=document.getElementById('spAssetResult');if(!key)return;box.className='sp-result show';box.textContent=ar?'جارٍ البحث...':'Searching...';try{const r=await fetch('{$assetLookup}?key='+encodeURIComponent(key),{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw new Error(d.message||'Not found');selectedAsset=d.asset;box.innerHTML='<b>'+esc(d.asset.asset_code)+' · '+esc(d.asset.name)+'</b><br>'+esc(d.asset.customer_name||'')+' · '+esc(d.asset.site_name||'');document.getElementById('spCompany').value=d.asset.customer_name||'';document.getElementById('spSite').value=d.asset.site_name||'';document.getElementById('spCity').value=d.asset.site_city||'';document.getElementById('spAddress').value=d.asset.site_address||'';document.getElementById('spPerson').value=d.asset.contact_name||document.getElementById('spPerson').value;document.getElementById('spMobile').value=d.asset.contact_mobile||document.getElementById('spMobile').value;setVal('asset_id',d.asset.id);setVal('asset_type',d.asset.type||'Other');setVal('equipment_brand',d.asset.brand||'');setVal('equipment_model',d.asset.model||'');setSummary()}catch(e){selectedAsset=null;box.innerHTML='<b style="color:#bd1f36">'+esc(ar?'لم يتم العثور على الأصل. تحقق من الرقم أو اختر أصل غير مسجل.':'Asset not found. Check the code or choose unregistered asset.')+'</b>'}});
const availabilityLabel=s=>s==='AVAILABLE'?(ar?'متوفر':'Available'):s==='LIMITED'?(ar?'كمية محدودة':'Limited'):(ar?'غير متوفر':'Not available');
document.getElementById('spPartLookup').addEventListener('click',loadParts);async function loadParts(){const q=document.getElementById('spPartSearch').value.trim(),wrap=document.getElementById('spParts');wrap.innerHTML='<div class="sp-note">'+(ar?'جارٍ التحقق من المستودع...':'Checking inventory...')+'</div>';try{const u=new URL('{$partsLookup}',location.origin);if(q)u.searchParams.set('q',q);if(selectedAsset?.id)u.searchParams.set('asset_id',selectedAsset.id);const r=await fetch(u,{headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok)throw new Error('lookup');if(!d.items.length){wrap.innerHTML='<div class="sp-note">'+(ar?'لا توجد نتائج. أدخل بيانات القطعة يدويًا أو اطلب المساعدة.':'No results. Enter the part manually or request help.')+'</div>';return}wrap.innerHTML=d.items.map((p,i)=>{const st=availabilityLabel(p.availability),cl=p.availability==='AVAILABLE'?'ok':p.availability==='LIMITED'?'low':'no';return '<div class="sp-part"><div><strong>'+esc(p.name)+'</strong><small>'+esc(p.item_code)+(p.compatible?' · '+(ar?'متوافق مع الأصل':'Compatible'):'')+'</small></div><div>'+esc(p.manufacturer_part_no||p.alternative_part_no||'—')+'</div><span class="sp-status '+cl+'">'+esc(st)+'</span><button type="button" data-pick="'+i+'">'+esc(ar?'اختيار':'Select')+'</button></div>'}).join('');wrap.querySelectorAll('[data-pick]').forEach(b=>b.addEventListener('click',()=>{selectedPart=d.items[+b.dataset.pick];selectedAvailability=availabilityLabel(selectedPart.availability);document.getElementById('spPartName').value=selectedPart.name;document.getElementById('spPartNo').value=selectedPart.item_code;document.getElementById('spOem').value=selectedPart.manufacturer_part_no||selectedPart.alternative_part_no||'';document.getElementById('spSelectedPart').textContent=(ar?'تم اختيار: ':'Selected: ')+selectedPart.item_code+' · '+selectedPart.name+' · '+selectedAvailability;setSummary()}))}catch(e){wrap.innerHTML='<div class="sp-note">'+(ar?'تعذر قراءة المخزون الآن. يمكنك إدخال القطعة يدويًا وسيتم التحقق منها أثناء مراجعة التذكرة.':'Inventory lookup is temporarily unavailable. Enter the part manually; it will be checked during ticket review.')+'</div>'}}
['spCompany','spAssetType','spPartName','spPartNo'].forEach(id=>document.getElementById(id).addEventListener('input',setSummary));
form.addEventListener('submit',e=>{if(!isSpare())return;const registered=document.querySelector('input[name=sp_asset_mode]:checked').value==='registered';if(registered&&!selectedAsset){e.preventDefault();alert(ar?'ابحث عن الأصل المسجل واختره، أو اختر أصل غير مسجل.':'Find the registered asset or choose unregistered asset.');return}const company=document.getElementById('spCompany').value.trim(),person=document.getElementById('spPerson').value.trim(),mobile=document.getElementById('spMobile').value.trim(),email=document.getElementById('spEmail').value.trim(),site=document.getElementById('spSite').value.trim(),city=document.getElementById('spCity').value.trim();if(!company||!person||!mobile||!email||!site||!city){e.preventDefault();alert(ar?'أكمل بيانات العميل والموقع المطلوبة.':'Complete the required customer and site fields.');return}const partName=document.getElementById('spPartName').value.trim(),partNo=document.getElementById('spPartNo').value.trim(),dontKnow=document.getElementById('spDontKnow').checked;if(!dontKnow&&!partName&&!partNo){e.preventDefault();alert(ar?'اختر قطعة من المستودع أو أدخل بياناتها أو اختر "لا أعرف القطعة".':'Select a part, enter it manually, or choose I do not know the part.');return}setVal('company_name',company);setVal('responsible_person',person);setVal('mobile',mobile);setVal('email',email);setVal('site_name',site);setVal('site_address',document.getElementById('spAddress').value);setVal('site_area',document.getElementById('spArea').value);setVal('site_city',city);setVal('urgency',document.getElementById('spPriority').value);setVal('requested_date',document.getElementById('spDate').value);setVal('requested_time',document.getElementById('spTime').value);setVal('service_category','Spare Parts');if(!registered){setVal('asset_id','');setVal('asset_type',document.getElementById('spAssetType').value||'Other');setVal('equipment_brand',document.getElementById('spBrand').value);setVal('equipment_model',document.getElementById('spModel').value)}const lines=[ar?'[طلب قطع غيار]':'[Spare Parts Request]',(ar?'حالة العميل: ':'Customer: ')+document.querySelector('input[name=sp_customer_mode]:checked').value,(ar?'حالة الأصل: ':'Asset: ')+(registered?'registered':'unregistered'),selectedAsset?('Asset: '+selectedAsset.asset_code+' | '+selectedAsset.name):('Asset details: '+document.getElementById('spAssetType').value+' | '+document.getElementById('spBrand').value+' | '+document.getElementById('spModel').value+' | Serial: '+document.getElementById('spSerial').value),(ar?'القطعة: ':'Part: ')+(partName||'Unknown'),(ar?'رقم القطعة: ':'Part No: ')+(partNo||'—'),'OEM: '+(document.getElementById('spOem').value||'—'),(ar?'الكمية: ':'Qty: ')+document.getElementById('spQty').value,(ar?'حالة المخزون عند الطلب: ':'Inventory at request: ')+(selectedAvailability||'TO_BE_CHECKED'),(ar?'نوع الطلب: ':'Request type: ')+document.getElementById('spRequestType').value,(ar?'ملاحظات: ':'Notes: ')+(document.getElementById('spNotes').value||'—')];setVal('details',lines.join('\n'));setVal('service_other',partNo||partName||'Spare Parts');});
});
</script>
HTML;

        $response->setContent(str_replace('</body>', $injection.'</body>', $html));
